const contentTypes = [
  { type: 'bridal_transformation', prompt: 'Write an Instagram Reel caption for Sahni Bridal Studio (@sahnibridalstudio) about a bridal transformation. Start with a powerful hook in Hindi or Hinglish that stops the scroll (e.g. "Jab dulhan ready hoti hai toh..."). Show emotion — the bride feeling beautiful, family reactions, the moment. 3-4 lines max. End with CTA: "Apni booking ke liye WhatsApp karo: 9098909088".' },
  { type: 'services_showcase', prompt: 'Write an Instagram caption for Sahni Bridal Studio (@sahnibridalstudio) showcasing their services: Bridal Makeup, Bridal Jewellery, Bridal Outfit, Engagement Makeup, Party Makeup, Hair Styling, Facial, Nail Art, Hair Spa. Use Hinglish. Start with a hook. Make it feel aspirational. End with CTA to WhatsApp 9098909088.' },
  { type: 'legacy_trust', prompt: 'Write an Instagram caption for Sahni Bridal Studio (@sahnibridalstudio). Highlight that they have been making brides beautiful since 1994 — 30+ years of trust in Lahar, Madhya Pradesh. Mention that thousands of brides have chosen them. Emotional, proud tone in Hinglish. End with CTA to WhatsApp 9098909088.' },
  { type: 'bridal_tips', prompt: 'Write an Instagram carousel caption for Sahni Bridal Studio (@sahnibridalstudio) giving 5 bridal makeup tips for Indian brides. Practical, helpful. Hinglish. Position them as the expert. End with: "Expert bridal makeup ke liye WhatsApp karo: 9098909088".' },
  { type: 'engagement_special', prompt: 'Write an Instagram Reel caption for Sahni Bridal Studio (@sahnibridalstudio) about engagement makeup. Hook should be about the "roka/engagement" moment. Romantic, emotional Hinglish. Services: Engagement Makeup, Jewellery, Outfit. CTA: WhatsApp 9098909088.' },
  { type: 'party_season', prompt: 'Write an Instagram caption for Sahni Bridal Studio (@sahnibridalstudio) for party/function makeup. Festive energy — shaadi season, sangeet, mehndi, reception. Fun Hinglish tone. Services: Party Makeup, Party Outfit, Party Jewellery. CTA: WhatsApp 9098909088.' }
];
const today = new Date();
const pick = contentTypes[today.getDay() % contentTypes.length];
return [{ json: { contentType: pick.type, promptText: pick.prompt, business: 'Sahni Bridal Studio', platform: 'Instagram', instagram: '@sahnibridalstudio' } }];

const b = $input.item.json;
const fullPrompt = b.promptText + ' Respond ONLY in valid JSON: {"hook":"first 1-2 lines that stop the scroll","caption":"full post caption in Hinglish","reelConcept":"what to show visually in the Reel (2 sentences)","hashtags":"15 hashtags mix of Hindi bridal + local MP + niche","platform":"Instagram"}';

return { json: {
  ...b,
  groqBody: JSON.stringify({
    model: 'llama-3.3-70b-versatile',
    messages: [
      { role: 'system', content: 'You are a top Indian social media content creator specialising in bridal beauty salons. You write viral Hinglish captions that get saves and shares. Always respond with valid JSON only. No markdown, no explanation.' },
      { role: 'user', content: fullPrompt }
    ],
    max_tokens: 500,
    temperature: 0.85
  })
}};

const raw = $input.item.json;
const prev = $('Build Groq Request').item.json;

let text = (raw.choices && raw.choices[0]?.message?.content) || '';
let hook = '', caption = text, reelConcept = '', hashtags = '';
try {
  const cleaned = text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  hook = parsed.hook || '';
  caption = parsed.caption || text;
  reelConcept = parsed.reelConcept || '';
  hashtags = parsed.hashtags || '';
} catch(e) {}

return { json: {
  business: prev.business,
  contentType: prev.contentType,
  platform: 'Instagram',
  hook,
  caption,
  reelConcept,
  hashtags
}};
